import json
def box_of(I):
    rows=[r for r in range(len(I)) if 1 in I[r]]
    cols=[c for c in range(len(I[0])) if any(I[r][c]==1 for r in range(len(I)))]
    return np.array([row[cols[0]:cols[-1]+1] for row in I[rows[0]:rows[-1]+1]]), rows[0], cols[0]
def antiT(bi):
    h,w=bi.shape
    return np.array([[bi[h-1-j][w-1-i] for j in range(w)] for i in range(h)])
def transpose(bi):
    return np.array([[bi[j][i] for j in range(len(bi))] for i in range(len(bi[0]))])
def solve(I, mode):
    b,r0,c0=box_of(I); bi=b[1:-1,1:-1]
    oi = antiT(bi) if mode=='anti' else transpose(bi)
    H,W=oi.shape
    out=np.ones((H+2,W+2),int)
    out[1:-1,1:-1]=oi
    return [list(map(int,r)) for r in out]
